function renderCandidates() {
  const body = $('#candBody'), note = $('#candNote'), head = $('#candHead');
  if (!body) return;
  const cf = (typeof CFG !== 'undefined' && CFG) ? CFG : (window.PANEL_CONFIG || null);
  const cands = (cf && Array.isArray(cf.candidates)) ? cf.candidates : [];
  const COLS = 15;
  if (!cands.length) {
    body.innerHTML = '<tr><td colspan="' + COLS + '" class="dim" style="text-align:center;padding:16px">config.js 未提供 candidates（请重跑 final_portfolio_v3.py 生成候选清单）。</td></tr>';
    note.textContent = '';
    return;
  }
  const onlyHit = document.getElementById('candOnlyHit') && document.getElementById('candOnlyHit').checked;
  const list = onlyHit ? cands.filter(c => c.in_buy_list || c.is_position) : cands;
  if (head) head.textContent = '沪深筛选层入选池 · 共 ' + cands.length + ' 只' + (onlyHit ? '（筛后 ' + list.length + '）' : '');
  const nz = v => (v == null || v === '' || !isFinite(v)) ? '—' : v;
  body.innerHTML = list.map(c => {
    const inB = !!c.in_buy_list, pos = !!c.is_position;
    let badge, cls = '';
    if (inB) { badge = '✅买入清单'; cls = 'pos'; }
    else if (pos) { badge = '持仓·不加仓'; cls = 'warn'; }
    else if (c.gap_pct != null && c.gap_pct <= 0) { badge = '达买点'; cls = 'pos'; }
    else if (c.gap_pct != null && c.gap_pct <= 10) { badge = '观察(缓冲带)'; }
    else { badge = '未达/剔除'; }
    if (c.gap_pct != null && c.gap_pct > 10) cls = 'neg';
    const gapTxt = c.gap_pct == null ? '—' : (c.gap_pct > 0 ? '+' + fmt(c.gap_pct, 1) + '%' : fmt(c.gap_pct, 1) + '%');
    return '<tr>'
      + '<td class="' + cls + '"><b>' + esc(c.name) + '</b><br><small class="tx3">' + esc(c.code) + '</small></td>'
      + '<td>' + esc(c.mkt || '') + '</td>'
      + '<td><small>' + esc(c.ind || '—') + '</small></td>'
      + '<td class="num">' + nz(fmt(c.px, 2)) + '</td>'
      + '<td class="num">' + nz(fmt(c.vwap60, 2)) + '</td>'
      + '<td class="num">' + nz(fmt(c.yld_ttm, 2)) + '%</td>'
      + '<td class="num">' + nz(fmt(c.yld3, 2)) + '%</td>'
      + '<td class="num">' + nz(fmt(c.dps, 3)) + '</td>'
      + '<td class="num">' + nz(fmt(c.target_yld, 2)) + '%</td>'
      + '<td class="num"><b>' + nz(fmt(c.target_price, 2)) + '</b></td>'
      + '<td class="num ' + cls + '">' + gapTxt + '</td>'
      + '<td class="num">' + nz(fmt(c.pay, 1)) + '%</td>'
      + '<td class="num">' + nz(fmt(c.ocfd, 2)) + '</td>'
      + '<td class="num">' + nz(fmt(c.vol, 1)) + '%</td>'
      + '<td>' + badge + '</td>'
      + '</tr>';
  }).join('');
  note.innerHTML = '目标买价 = DPS ÷ 行业目标股息率（金融 fixed 5.5% / 周期 8.0% / 其余 dynamic：三年均股息+垫，下限 3.0%）。'
    + '距买点 = 现价/目标价 − 1：<span class="tx3">≤0 达买点、0~10% 观察缓冲带、&gt;10% 剔除</span>。'
    + '本表为筛选层入选池全览，仅展示，买入以「买入推荐」为准。';
  const cb = document.getElementById('candOnlyHit');
  if (cb && !cb._bound) { cb._bound = true; cb.onchange = renderCandidates; }
}

